theme.css:
/* theme: Blueprint Rally | A nervous market steadied by traders while courts and coalitions chart new paths, drawn in engineer's blue. */
/* mood: neutral */
/* layout: hero=poster; major-events=numbered/stack; political-news=lede/stack; financial-news=stat/feature; entertainment-news=tile/grid-2; sports=banner/grid-3; music-releases=plain/stack; stock-analysis=split/grid-2; outlook=outline/stack */
.diary-page {
  --paper: #f4f6f7;
  --paper-alt: #e2e4e6;
  --ink: #141a1d;
  --ink-soft: #2b3438;
  --muted: #58646b;
  --accent: #3a4a52;
  --accent-ink: #ffffff;
  --rule: #c3cdd3;
  --font-display: var(--ff-exo), var(--ff-space-grotesk), sans-serif;
  --font-body: var(--ff-newsreader), Georgia, serif;
  --font-ui: var(--ff-space-grotesk), system-ui, sans-serif;
}

.diary-page[data-hero="poster"] .diary-hero {
  background: linear-gradient(135deg, #3a4a52 0%, #4a5a62 100%);
}

.diary-page[data-hero="poster"] .diary-title {
  font-size: clamp(3.5rem, 12vw, 8.5rem);
  letter-spacing: -0.06em;
  line-height: 0.9;
  text-transform: none;
  font-weight: 700;
}

.diary-page[data-hero="poster"] .diary-summary {
  max-width: 34rem;
  border-left: 0.25rem solid var(--accent-ink);
  padding-left: 1.25rem;
  margin-left: 0.25rem;
}

.diary-page[data-hero="poster"] .diary-theme-name {
  background: var(--accent-ink);
  color: var(--accent);
}

.diary-page .diary-kicker {
  letter-spacing: 0.4em;
  text-transform: uppercase;
  font-weight: 700;
}

.diary-page .diary-crumbs a {
  color: var(--accent-ink);
  opacity: 0.9;
}

.diary-page .diary-crumbs a::before {
  content: "⟵ ";
}

.diary-page .diary-toc {
  background: color-mix(in srgb, var(--paper) 92%, transparent);
}

.diary-page .diary-toc-label {
  font-weight: 700;
  letter-spacing: 0.25em;
}

.diary-page .diary-toc-link.is-active,
.diary-page .diary-toc-number {
  color: var(--accent);
}

.diary-page .diary-section {
  border-top-color: var(--rule);
}

.diary-page .diary-section-head {
  border-bottom: 0.15rem solid var(--ink);
  padding-bottom: 0.75rem;
  margin-bottom: 2.5rem;
}

.diary-page .diary-section-number {
  background: var(--accent);
  color: var(--accent-ink);
  font-size: 0.7rem;
  font-weight: 700;
  padding: 0.2rem 0.6rem;
  border-radius: 0.15rem;
  line-height: 1.4;
}

.diary-page .diary-section-title {
  font-weight: 700;
  letter-spacing: -0.03em;
  font-size: clamp(1.5rem, 3vw, 2rem);
  text-transform: lowercase;
}

.diary-page .diary-section-title::after {
  content: " /";
  color: var(--accent);
}

.diary-page[data-section="major-events"] .diary-stories--stack {
  max-width: 42rem;
}

.diary-page[data-section="major-events"] .diary-card--numbered .diary-card-inner {
  grid-template-columns: 3.5rem minmax(0, 1fr);
  column-gap: 1.75rem;
  row-gap: 0.4rem;
}

.diary-page[data-section="major-events"] .diary-card--numbered .diary-card-index {
  grid-row: 1 / span 2;
  font-size: 3.5rem;
  font-weight: 700;
  color: var(--accent);
  opacity: 0.35;
  letter-spacing: -0.06em;
}

.diary-page[data-section="major-events"] .diary-card-title {
  font-size: 1.15rem;
  font-weight: 600;
  margin-bottom: 0.15rem;
}

.diary-page[data-section="major-events"] .diary-card-body {
  font-size: 1.05rem;
  line-height: 1.65;
}

.diary-page[data-section="major-events"] .diary-card--numbered + .diary-card--numbered {
  margin-top: 1.25rem;
  padding-top: 1.25rem;
  border-top: 0.05rem dashed var(--rule);
}

.diary-page[data-section="political-news"] .diary-card--lede .diary-card-lede {
  font-size: 1.35rem;
  border-left-color: var(--accent);
  padding-left: 1.1rem;
}

.diary-page[data-section="financial-news"] .diary-card--stat .diary-card-inner {
  border-top: 0.2rem solid var(--accent);
  padding-top: 0.25rem;
}

.diary-page[data-section="financial-news"] .diary-card-figure {
  font-size: clamp(3rem, 10cqi, 5rem);
  letter-spacing: -0.04em;
}

.diary-page .diary-card--tile .diary-card-inner {
  background: var(--paper-alt);
  border-left: 0.2rem solid var(--accent);
  padding: 1.25rem 1.5rem;
}

.diary-page[data-section="entertainment-news"] .diary-card--tile .diary-card-title {
  font-size: 1.25rem;
}

.diary-page[data-section="sports"] .diary-card--banner .diary-card-inner {
  border: 0.05rem solid var(--rule);
  border-radius: 0;
}

.diary-page[data-section="sports"] .diary-card--banner .diary-card-title {
  background: var(--accent);
  padding: 0.6rem 1.25rem;
  font-size: 1rem;
}

.diary-page[data-section="sports"] .diary-card--banner .diary-card-body {
  padding: 1rem 1.25rem;
}

.diary-page[data-section="music-releases"] .diary-card--plain {
  padding-bottom: 1.5rem;
}

.diary-page[data-section="music-releases"] .diary-card--plain .diary-card-title {
  font-size: 1.3rem;
  font-weight: 500;
  margin-bottom: 0.4rem;
}

.diary-page[data-section="music-releases"] .diary-card--plain .diary-card-title::before {
  content: "▶ ";
  color: var(--accent);
  font-size: 0.7em;
  vertical-align: middle;
}

.diary-page[data-section="stock-analysis"] .diary-stories--grid-2 {
  gap: 1.5rem;
}

.diary-page[data-section="stock-analysis"] .diary-card--split .diary-card-inner {
  border-top-color: var(--accent);
  padding-top: 1.25rem;
}

.diary-page[data-section="stock-analysis"] .diary-card--split .diary-card-title {
  font-size: 1.1rem;
  font-weight: 600;
  letter-spacing: -0.02em;
}

.diary-page[data-section="stock-analysis"] .diary-card--split .diary-card-body {
  font-size: 1.02rem;
  line-height: 1.6;
}

.diary-page[data-section="outlook"] .diary-card--outline .diary-card-inner {
  border-radius: 0;
  border-left-width: 0.25rem;
  border-left-color: var(--accent);
  padding: 1.4rem 1.5rem;
}

.diary-page[data-section="outlook"] .diary-card--outline .diary-card-title {
  font-family: var(--font-ui);
  font-size: 0.95rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.diary-page .diary-card-thread {
  border-radius: 0;
  font-weight: 600;
}

.diary-page .diary-prose {
  color: var(--ink-soft);
}

.diary-page .diary-prose a {
  color: var(--accent);
  border-bottom: none;
  background: linear-gradient(var(--accent), var(--accent)) no-repeat 0 100% / 100% 0.1em;
}

.diary-page .diary-prose a:hover {
  color: var(--ink);
}

.diary-page .diary-prose strong {
  color: var(--ink);
  font-weight: 650;
}

.diary-page .diary-prose blockquote {
  border-left-color: var(--accent);
  padding-left: 1rem;
  font-weight: 350;
}

.diary-page .diary-prose ul > li::before {
  background: var(--accent);
  width: 0.75rem;
  height: 0.1rem;
}

.diary-page .diary-markets {
  grid-template-columns: repeat(auto-fill, minmax(8rem, 1fr));
  gap: 0.5rem;
}

.diary-page .diary-spark {
  background: var(--paper-alt);
  border-radius: 0;
  border-color: var(--rule);
  padding: 0.6rem 0.7rem 0.5rem;
}

.diary-page .diary-spark-label {
  font-weight: 600;
  letter-spacing: 0.08em;
}

.diary-page .diary-spark-change {
  font-weight: 700;
}

.diary-page .diary-spark-line {
  stroke: currentColor;
  stroke-width: 1.5;
  fill: none;
}

.diary-page .diary-spark.is-down {
  color: var(--accent);
}

.diary-page .diary-footer {
  border-top-color: var(--rule);
  font-weight: 500;
}

.diary-page .diary-footer a:hover {
  color: var(--accent);
}
